    const opts = (part, list) => none(part) + list.filter(ok).map((v) => pic(set(cur, part, v), n[part] === v, v, `${part}|${v}`) .replace('class="avo', LOCKED.includes(v) ? 'class="avo lvx' : 'class="avo')).join('');
