      rows.forEach((r) => Object.entries(r.z).forEach(([n, t]) => { if (!cnt[n]) cnt[n] = [0, 0, 0, 0, 0, 0, 0]; (t || []).forEach((d) => { const x = r.r[`${n}|${d}`]; cnt[n][d - 1] += x && x[0] > 1 ? 1 / x[0] : 1; }); }));
