    const ic = b.kind === 'holiday' ? '🌴' : '✈️'; let txt;
    if (b.state === 'tomorrow') txt = b.at ? TX.awTomAt.replace('{t}', b.at) : TX.awTom;
    else if (b.state === 'today') txt = TX.awAt.replace('{t}', b.at);
