      const pass = (r, f) => f === 'all' || (f === 'daily' ? Object.values(r.z).some((t) => (t || []).length === 7) : f === 'rhythm' ? hasRf(r)
        : f === 'none' ? !Object.values(r.z).some((t) => (t || []).length) : f.startsWith('p:') ? ((r.z[f.slice(2)] || []).length > 0) : true);
