      if (s.type === 'monthly') return s.mode === 'weekday' ? T.sum.monthly_wd(s, T.nths[String(s.nth)], T.wdl[s.weekday - 1]) : T.sum.monthly_day(s);
      if (s.type === 'yearly') return T.sum.yearly(s.dates.map((d) => this._fmtMd(d)).join(', '));
