      if (sc.type === 'monthly') Object.assign(sched, { every: sc.every || 1, start: sc.start, mode: sc.mode, ...(sc.mode === 'weekday' ? { nth: sc.nth, weekday: sc.weekday } : { day: sc.day }) });
      if (sc.type === 'yearly' || sc.type === 'once') sched.dates = sc.dates;
